.lm-tab{min-width:0;padding:0 5px;display:inline-flex;align-items:center;justify-content:center;gap:5px;white-space:normal;line-height:1.2;font-size:10px;font-weight:500;color:#918784;transition:color .16s ease}
.lm-tab:hover,.lm-tab.active{color:#741820}
.lm-tab.active{font-weight:700}
.lm-tab:after{left:18%;right:18%;bottom:0;height:3px;border-radius:999px 999px 0 0;background:#7B1921;opacity:0;transform:scaleX(.55);transition:opacity .16s ease,transform .16s ease}
