<label class="lm-search"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/></svg><input id="lmSearch" type="search" placeholder="Search conversations" aria-label="Search conversations"></label><div id="lmThreads" class="lm-thread-list"></div></aside>
<section class="lm-chat" id="lmChatPanel" aria-label="Conversation"><header class="lm-header"><button class="lm-chat-back" type="button" id="lmBack" aria-label="Back to conversations">‹</button><div class="lm-avatar" id="lmChatAvatar">SE</div><div class="lm-heading"><h2 id="lmChatName">Select a conversation</h2><p id="lmChatSub">Choose a contact to view messages</p></div><span class="lm-header-badge" id="lmChatBadge">Messages</span></header>
<div class="lm-context" id="lmContext" hidden><div><span id="lmContextLabel">Network contact</span><strong id="lmContextValue"></strong></div></div><div class="lm-chat-body" id="lmBody"><div class="lm-empty-chat"><svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 14h42v31H25L13 55V45h-2V14Z"/><path d="M20 25h24M20 33h17"/></svg><strong>No selected chat</strong>Selected conversation will appear here.</div></div>
<form class="lm-composer" id="lmForm" hidden><div class="lm-compose-row"><textarea id="lmText" placeholder="Type a message..." rows="1" maxlength="3000"></textarea><label class="lm-attach" for="lmAttachment" title="Attach a file" aria-label="Attach a file">📎</label><input type="file" id="lmAttachment" hidden><button class="lm-send" type="submit" aria-label="Send message"><img src="{{ asset('icons/buyer/send.png') }}" alt="" width="19" height="19"></button></div><div id="lmAttachmentPreview" class="lm-attachment-preview" hidden><span id="lmAttachmentName"></span><button type="button" id="lmAttachmentRemove" aria-label="Remove attachment">×</button></div><p class="lm-compose-note">Messages and attachments are saved to your account when the Sorting Center messaging API is connected. Files may be up to 15 MB.</p></form>
</section></div></main><div class="lm-toast" id="lmToast" hidden role="status"></div>
<script>
document.addEventListener('DOMContentLoaded',async()=>{
'use strict';
const API_BASE = @json(url('/api/v1/sorting-center/messages'));
 const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s??'').toLowerCase().trim(), initials=s=>String(s||'').split(/\s+/).slice(0,2).map(w=>w[0]||'').join('').toUpperCase();
let tab='admin',current=null,contacts=[],busy=false;
const toast=txt=>{ $('lmToast').textContent=txt;$('lmToast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('lmToast').hidden=true,3400); };
async function api(url,options={}){const formData=options.body instanceof FormData,headers={Accept:'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content||'',...(options.headers||{})};if(!formData)headers['Content-Type']='application/json';const response=await fetch(url,{credentials:'same-origin',...options,headers});const json=await response.json().catch(()=>({}));if(!response.ok)throw new Error(json.message||'Unable to load messages.');return json;}
function typeOf(c){return c.type==='admin'?'admin':c.type==='logistics'?'logistics':'delivery';}
function stamp(v){if(!v)return '';const d=new Date(v);return Number.isNaN(d.getTime())?'':new Intl.DateTimeFormat('en-PH',{hour:'numeric',minute:'2-digit',hour12:true}).format(d);}
async function refresh(){try{const result=await api(API_BASE);contacts=(Array.isArray(result.data)?result.data:[]).filter(c=>['admin','logistics','delivery'].includes(c.type));if(current&&!contacts.some(c=>c.key===current))current=null;renderList();renderChat();}catch(e){toast(e.message);}}
function renderList(){const query=norm($('lmSearch').value),typeMap={admin:'admin',logistics:'logistics',delivery:'delivery'};
for(const type of ['admin','logistics','delivery']){$('lmCount'+type[0].toUpperCase()+type.slice(1)).textContent=contacts.filter(c=>typeMap[c.type]===type).length;}
const filtered=contacts.filter(c=>typeMap[c.type]===tab&&norm(c.name+' '+c.sub+' '+c.detail).includes(query));
$('lmThreads').innerHTML=filtered.length?filtered.map(c=>{const last=(c.messages||[]).at(-1);return `<button type="button" class="lm-thread ${current===c.key?'active':''}" data-key="${esc(c.key)}"><span class="lm-avatar ${c.type==='admin'?'admin':c.type==='delivery'?'hub':'logistics'}">${esc(initials(c.name))}</span><span class="lm-thread-copy"><span class="lm-thread-top"><strong>${esc(c.name)}</strong><time>${esc(stamp(last?.at||c.last_message_at))}</time></span><p>${esc(last?.text||c.preview||c.sub)}</p></span>${c.unread?'<span class="lm-unread">'+Number(c.unread)+'</span>':''}</button>`}).join(''):'<div class="lm-list-empty">No conversations found in this category.</div>';}
function renderChat(){const contact=contacts.find(c=>c.key===current);if(!contact){$('lmShell').classList.remove('has-selection');$('lmChatName').textContent='Select a conversation';$('lmChatSub').textContent='Choose a contact to view messages';$('lmChatBadge').textContent='Messages';$('lmChatAvatar').textContent='SE';$('lmChatAvatar').className='lm-avatar';$('lmContext').hidden=true;$('lmForm').hidden=true;$('lmBody').innerHTML='<div class="lm-empty-chat"><strong>No selected chat</strong>Choose a contact to view messages.</div>';return;}
$('lmShell').classList.add('has-selection');$('lmChatName').textContent=contact.name;$('lmChatSub').textContent=contact.sub;$('lmChatBadge').textContent=contact.type==='admin'?'Admin':contact.type==='logistics'?'Logistics':'Delivery Hub';$('lmChatAvatar').textContent=initials(contact.name);$('lmChatAvatar').className='lm-avatar '+(contact.type==='admin'?'admin':contact.type==='delivery'?'hub':'logistics');$('lmContextLabel').textContent=contact.type==='admin'?'Platform contact':'Contact location';$('lmContextValue').textContent=contact.detail||'—';$('lmContext').hidden=false;$('lmForm').hidden=false;
const history=contact.messages||[];let dayKey='';$('lmBody').innerHTML=history.length?history.map(m=>{const d=new Date(m.at),valid=!Number.isNaN(d.getTime()),day=valid?d.toLocaleDateString('en-CA',{timeZone:'Asia/Manila'}):'unknown';let divider='';if(day!==dayKey){dayKey=day;divider='<div class="lm-date-divider"><span>'+esc(valid?new Intl.DateTimeFormat('en-PH',{timeZone:'Asia/Manila',month:'short',day:'numeric',year:'numeric'}).format(d):'Earlier messages')+'</span></div>';}const file=m.attachment_url?`<a class="lm-attachment" href="${esc(m.attachment_url)}" target="_blank" rel="noopener">📎 ${esc(m.attachment_name||'Download attachment')}</a>`:'';const body=m.text?`<div class="bubble">${esc(m.text)}</div>`:'';return divider+`<div class="lm-msg ${m.mine?'mine':''}">${body}${file}<time>${esc(stamp(m.at))}</time></div>`;}).join(''):'<div class="lm-empty-chat"><strong>Start a conversation</strong>Send a message or attach a file to this contact.</div>';$('lmBody').scrollTop=$('lmBody').scrollHeight;}
$('lmThreads').addEventListener('click',async e=>{const button=e.target.closest('[data-key]');if(!button)return;current=button.dataset.key;renderList();renderChat();const contact=contacts.find(c=>c.key===current);if(!contact)return;try{const result=await api(API_BASE+'/thread',{method:'POST',body:JSON.stringify({type:contact.type,contact_id:contact.contact_id})});contact.conversation_id=result.data.conversation_id;contact.messages=result.data.messages||[];renderChat();}catch(err){toast(err.message);}});
document.querySelectorAll('.lm-tab').forEach(button=>button.addEventListener('click',()=>{tab=button.dataset.tab;current=null;document.querySelectorAll('.lm-tab').forEach(x=>{x.classList.toggle('active',x===button);x.setAttribute('aria-selected',String(x===button))});renderList();renderChat();}));
$('lmSearch').addEventListener('input',renderList);$('lmBack').addEventListener('click',()=>$('lmShell').classList.remove('has-selection'));
$('lmAttachment').addEventListener('change',()=>{const file=$('lmAttachment').files?.[0];$('lmAttachmentPreview').hidden=!file;$('lmAttachmentName').textContent=file?`${file.name} (${(file.size/1024/1024).toFixed(2)} MB)`:'';});$('lmAttachmentRemove').addEventListener('click',()=>{$('lmAttachment').value='';$('lmAttachmentPreview').hidden=true;});
$('lmForm').addEventListener('submit',async e=>{e.preventDefault();const contact=contacts.find(c=>c.key===current),body=$('lmText').value.trim(),file=$('lmAttachment').files?.[0];if(!contact||(!body&&!file)||busy)return;if(file&&file.size>15*1024*1024){toast('The maximum attachment size is 15 MB.');return;}busy=true;$('lmForm').querySelector('button[type=submit]').disabled=true;try{const payload=new FormData();payload.append('type',contact.type);payload.append('contact_id',contact.contact_id);if(body)payload.append('body',body);if(file)payload.append('attachment',file);const result=await api(API_BASE,{method:'POST',body:payload});contact.conversation_id=result.data.conversation_id;contact.messages=[...(contact.messages||[]),result.data.message];$('lmText').value='';$('lmAttachment').value='';$('lmAttachmentPreview').hidden=true;renderList();renderChat();toast('Message sent.');}catch(err){toast(err.message);}finally{busy=false;$('lmForm').querySelector('button[type=submit]').disabled=false;}});
$('lmText').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('lmForm').requestSubmit();}});
$('lgSidebarToggle')?.addEventListener('click',()=>{document.body.classList.toggle('lg-collapsed');$('lgSidebarToggle').setAttribute('aria-expanded',String(!document.body.classList.contains('lg-collapsed')))});$('lgProfileButton')?.addEventListener('click',()=>{const m=$('lgProfileMenu');m.hidden=!m.hidden;$('lgProfileButton').setAttribute('aria-expanded',String(!m.hidden))});$('lgChangeProfilePhoto')?.addEventListener('click',()=>$('lgProfilePhotoInput')?.click());$('lgProfilePhotoInput')?.addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5*1024*1024){toast('Use a JPG, PNG or WebP under 5 MB.');e.target.value='';return}const d=new FormData;d.append('profile_photo',f);try{const r=await fetch('/api/v1/profile/photo',{method:'PUT',credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content||''},body:d});const json=await r.json();if(!r.ok)throw Error(json.message||'Upload failed');const avatar=document.querySelector('#lgProfileButton .account-avatar');if(avatar){let img=avatar.querySelector('img');if(!img){img=document.createElement('img');avatar.append(img)}img.src=json.profile_photo_url;img.style.cssText='position:absolute;inset:0;width:100%;height:100%;border-radius:inherit;object-fit:cover'}toast('Profile photo updated.')}catch(err){toast(err.message||'Unable to update photo')}finally{e.target.value=''}});
document.addEventListener('click',e=>{if(!e.target.closest('.lg-profile-wrap')&&$('lgProfileMenu')){$('lgProfileMenu').hidden=true;$('lgProfileButton')?.setAttribute('aria-expanded','false')}});$('lgNotifyButton')?.addEventListener('click',()=>toast('No live notifications connected yet.'));
const params=new URLSearchParams(location.search),wantedTab=params.get('tab'),center=params.get('center'),hub=params.get('hub');
if((wantedTab==='logistics')||(wantedTab==='delivery'&&hub)){tab=wantedTab;document.querySelectorAll('.lm-tab').forEach(b=>{const selected=b.dataset.tab===tab;b.classList.toggle('active',selected);b.setAttribute('aria-selected',String(selected));});}
await refresh();
if((wantedTab==='logistics'&&params.get('logistics'))||(wantedTab==='delivery'&&hub)){const key=wantedTab==='logistics'?'logistics:'+String(params.get('logistics')||''):'delivery:'+hub;const contact=contacts.find(c=>c.key===key);if(contact){current=key;renderList();renderChat();try{const result=await api(API_BASE+'/thread',{method:'POST',body:JSON.stringify({type:contact.type,contact_id:contact.contact_id})});contact.conversation_id=result.data.conversation_id;contact.messages=result.data.messages||[];renderChat();}catch(e){toast(e.message);}}}
window.setInterval(()=>{if(!document.hidden)refresh();},20000);
});
</script></body></html>